"""API integration checks. Every test owns a temporary database and local server."""
import copy,csv,datetime,io,json,os,socket,sqlite3,subprocess,tempfile,time,unittest,urllib.request,urllib.error
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
DAY=datetime.date.today().isoformat()
MONTH=DAY[:7]

class BudgetAPI(unittest.TestCase):
 def setUp(self):
  self.temp=tempfile.TemporaryDirectory(prefix='budget-api-');self.dir=Path(self.temp.name);self.start()
 def start(self):
  with socket.socket() as sock:sock.bind(('127.0.0.1',0));self.port=sock.getsockname()[1]
  self.base=f'http://127.0.0.1:{self.port}';self.log=open(self.dir/'server.log','a')
  self.process=subprocess.Popen(['node',str(ROOT/'server.js')],cwd=self.dir,env={**os.environ,'PORT':str(self.port)},stdout=self.log,stderr=self.log)
  for _ in range(80):
   try:self.get('/api/state');return
   except (OSError,urllib.error.URLError):
    if self.process.poll() is not None:raise AssertionError((self.dir/'server.log').read_text())
    time.sleep(.05)
  raise AssertionError('Server readiness timeout')
 def stop(self):self.process.terminate();self.process.wait(timeout=10);self.log.close()
 def tearDown(self):self.stop();self.temp.cleanup()
 def call(self,path,data=None,status=200,headers=None,raw=False):
  req=urllib.request.Request(self.base+path,data=None if data is None else json.dumps(data).encode(),headers=headers or ({'Content-Type':'application/json'} if data is not None else {}))
  try:response=urllib.request.urlopen(req)
  except urllib.error.HTTPError as e:response=e
  with response:
   body=response.read();self.assertEqual(response.status,status,body.decode()[:600]);return body.decode('utf-8-sig') if raw else json.loads(body)
 def get(self,path):return self.call(path)
 def post(self,path,data,status=200):return self.call(path,data,status)
 def account(self,kind='checking',balance=1000):return self.post('/api/accounts',{'name':'Compte '+kind,'kind':kind,'balance':balance})['accounts'][0]['id']
 def transaction(self,account,amount=-10,**extra):return self.post('/api/transactions',{'account_id':account,'amount':amount,'description':'Épicerie','happened_on':DAY,**extra})
 def csv_data(self,account,text=None,**extra):return {'csv':text or f'Date;Description;Montant\n{DAY};Marché;-12,50\n{DAY};Salaire;100,00','account_id':account,'mapping':{'date':0,'description':1,'amount':2},'date_format':'ISO','affects_balance':False,**extra}
 def import_rows(self,payload,selected=None,**extra):
  preview=self.post('/api/import/preview',payload)
  return self.post('/api/import/commit',{**payload,'fingerprint':preview['fingerprint'],'selected_rows':selected or [r['row'] for r in preview['rows'] if not r.get('error') and not r.get('duplicate')],**extra})
 def test_v73_advance_follows_changed_schedule_and_deleted_envelope_is_pruned(self):
  self.account();first=self.future73(2);second=self.future73(4);payload={'name':'Date modifiée','reserved':0,'budget':230,'frequency':'weekly','start_on':first,'rollover':True,'forecast_spend':False};s=self.post('/api/envelopes',payload);eid=s['envelopes'][0]['id'];self.fund73(eid,100);s=self.post('/api/envelopes/update',{**payload,'id':eid,'reserved':100,'start_on':second});self.assertEqual(next(d for d in s['forecast'] if d['date']==first)['safe_cents'],90000);self.assertEqual(next(d for d in s['forecast'] if d['date']==second)['safe_cents'],77000);self.post('/api/envelopes/delete',{'id':eid});backup=self.get('/api/backup/export');self.post('/api/backup/validate',{'backup':backup});self.assertNotIn(str(eid),json.loads(next(a['value'] for a in backup['tables']['app_settings'] if a['key']=='envelope_advances_v73')))
 def test_v73_backup_rejects_corrupt_advance_and_demo_cannot_create_real_share(self):
  self.account();s=self.post('/api/envelopes',{'name':'Validation','reserved':100,'budget':230,'frequency':'weekly','start_on':self.future73(),'forecast_spend':False});backup=self.get('/api/backup/export');setting=next(a for a in backup['tables']['app_settings'] if a['key']=='envelope_advances_v73');setting['value']='{"123":{"not-a-date":{"amount_cents":-1}}}';self.post('/api/backup/validate',{'backup':backup},400);self.call('/api/sharing',{'action':'create'},headers={'Content-Type':'application/json','X-Budget-Workspace':'demo'},status=409);self.assertIsNone(self.get('/api/sharing')['path'])
 def test_v74_archived_goals_and_monthly_report_stay_consistent(self):
  self.account();cid=self.make_category('Objectif archivé');self.global74(cid,80);report=self.get('/api/monthly?month='+MONTH);self.assertEqual(next(r for r in report['budgets'] if r['id']==cid)['limit_cents'],8000);self.post('/api/categories/archive',{'id':cid,'archived':True,'expected_archived':0});r=next(r for r in self.global_state74()['rows'] if r['id']==cid);self.assertTrue(r['archived']);self.assertEqual(r['budget_cents'],8000);self.post('/api/categories/archive',{'id':cid,'archived':False,'expected_archived':1});self.global74(cid,0,repeat=False,clear=True);report=self.get('/api/monthly?month='+MONTH);self.assertIsNone(next(r for r in report['budgets'] if r['id']==cid)['limit_cents'])
 def test_v74_legacy_nonrepeating_target_does_not_reappear(self):
  self.account();cid=self.make_category('Ancien objectif ponctuel');args={'month':'2026-10','category_id':cid,'amount':230,'frequency':'weekly','start_on':'2026-10-01','repeat_monthly':False,'direction':'expense','mode':'target'};p=self.post('/api/budget/preview',args);self.post('/api/budget/apply',{**args,'token':p['token']});self.assertEqual(next(r for r in self.global_state74('2026-10')['rows'] if r['id']==cid)['budget_cents'],99667);self.assertIsNone(next(r for r in self.global_state74('2026-11')['rows'] if r['id']==cid)['budget_cents'])
 def test_v74_subcategory_goals_sum_parent_once_replace_old_goal_and_keep_safe(self):
  aid=self.account();cid=self.make_category('Paiement auto détaillé');alex=self.make_subcategory(cid,'Alex');jenny=self.make_subcategory(cid,'Jenny');self.global74(cid,999);before=self.get('/api/state');self.global74(cid,200,subcategory_id=alex);self.global74(cid,300,subcategory_id=jenny);s=self.global_state74();r=next(r for r in s['rows'] if r['id']==cid);self.assertEqual((r['budget_cents'],r['budget_mode']),(50000,'subcategories'));self.assertEqual(sum(x['budget_cents'] or 0 for x in s['rows']),50000);self.assertEqual([sub['budget_cents'] for sub in r['subcategories']],[20000,30000]);self.assertEqual(before['forecast'],self.get('/api/state')['forecast']);self.assertEqual(before['safe_cents'],self.get('/api/state')['safe_cents']);self.transaction(aid,-210,category_id=cid,subcategory_id=alex);self.transaction(aid,-100,category_id=cid,subcategory_id=jenny);self.transaction(aid,-20,category_id=cid);r=next(r for r in self.global_state74()['rows'] if r['id']==cid);self.assertEqual((r['actual_cents'],r['variance_cents'],r['unassigned_subcategory_cents']),(33000,17000,2000));self.assertEqual(r['subcategories'][0]['variance_cents'],-1000);self.assertEqual(r['overspent_subcategory_count'],1);self.assertEqual(r['unbudgeted_subcategory_count'],1)
 def test_v74_subcategory_frequencies_repeat_stop_copy_and_reopen_parent(self):
  self.account();cid=self.make_category('Détail renouvelable');a=self.make_subcategory(cid,'Semaine');b=self.make_subcategory(cid,'Ponctuel');self.global74(cid,230,month='2026-10',frequency='weekly',subcategory_id=a);self.global74(cid,80,month='2026-10',repeat=False,subcategory_id=b);r=next(r for r in self.global_state74('2026-10')['rows'] if r['id']==cid);self.assertEqual(r['budget_cents'],107667);r=next(r for r in self.global_state74('2026-11')['rows'] if r['id']==cid);self.assertEqual(r['budget_cents'],99667);self.assertIsNone(next(sub for sub in r['subcategories'] if sub['id']==b)['budget_cents']);self.global74(cid,0,month='2026-11',repeat=False,clear=True,subcategory_id=a);r=next(r for r in self.global_state74('2026-11')['rows'] if r['id']==cid);self.assertIsNone(r['budget_cents']);p=self.post('/api/budget/global-copy-preview',{'from':'2026-10','to':'2026-12'});self.assertEqual(len(p['rows'][0]['children']),2);self.post('/api/budget/global-copy',{'from':'2026-10','to':'2026-12','token':p['token']});r=next(r for r in self.global_state74('2026-12')['rows'] if r['id']==cid);self.assertEqual(r['budget_cents'],107667);self.assertEqual(r['budget_mode'],'subcategories');self.global74(cid,400,month='2026-12',replace_children=True);r=next(r for r in self.global_state74('2026-12')['rows'] if r['id']==cid);self.assertEqual((r['budget_cents'],r['budget_mode']),(40000,'category'));self.assertTrue(all(s['budget_cents'] is None for s in r['subcategories']));self.assertEqual(next(r for r in self.global_state74('2026-10')['rows'] if r['id']==cid)['budget_cents'],107667)
 def test_v74_subcategory_validation_income_refund_undo_restart_and_backup(self):
  aid=self.account();cid=self.make_category('Revenus détaillés');sid=self.make_subcategory(cid,'Alex');other=self.make_category('Autre parent');foreign=self.make_subcategory(other,'Étranger');self.global74(cid,1000,direction='income');args={'month':MONTH,'category_id':cid,'subcategory_id':foreign,'amount':100,'frequency':'monthly','repeat':True,'direction':'income'};self.post('/api/budget/global-preview',args,400);s=self.global74(cid,1200,direction='income',subcategory_id=sid);self.transaction(aid,1300,category_id=cid,subcategory_id=sid);r=next(r for r in self.global_state74()['rows'] if r['id']==cid);self.assertEqual((r['budget_cents'],r['actual_cents'],r['variance_cents']),(120000,130000,10000));backup=self.get('/api/backup/export');self.post('/api/backup/validate',{'backup':backup});s=self.global74(cid,1100,direction='income',subcategory_id=sid);self.post('/api/support/undo',{'token':s['support41']['undo']['token']});self.assertEqual(next(r for r in self.global_state74()['rows'] if r['id']==cid)['budget_cents'],120000);self.post('/api/backup/restore',{'backup':backup,'confirm':'REMPLACER'});self.stop();self.start();self.assertEqual(next(r for r in self.global_state74()['rows'] if r['id']==cid)['budget_cents'],120000);args['subcategory_id']=sid;args['direction']='expense';self.post('/api/budget/global-preview',args,400);next(x for x in backup['tables']['app_settings'] if x['key']=='global_budget_v74')['value']='{"plans":{},"subplans":{"999999":[]}}';self.post('/api/backup/validate',{'backup':backup},400)
