 def test_v80_split_same_card_envelope_keeps_protection_and_late_funding_intact(self):
  joint,personal,cards,eid=self.protected_groceries();s=self.transaction(cards[0],-100,envelope_id=eid,description='Costco');tid=s['transactions'][0]['id'];before=(s['safe_cents'],s['envelope_reserved_cents'],s['card_envelope_reserved_cents'],next(a for a in s['accounts'] if a['id']==cards[0])['balance_cents']);s=self.split80(tid,[{'amount':40,'envelope_id':eid},{'amount':60,'envelope_id':eid}]);self.assertEqual((s['safe_cents'],s['envelope_reserved_cents'],s['card_envelope_reserved_cents'],next(a for a in s['accounts'] if a['id']==cards[0])['balance_cents']),before)
