 def global74(self,cid,amount,month=MONTH,frequency='monthly',repeat=True,direction='expense',**extra):
  args={'month':month,'category_id':cid,'amount':amount,'frequency':frequency,'repeat':repeat,'direction':direction,**extra};p=self.post('/api/budget/global-preview',args);return self.post('/api/budget/global-apply',{**args,'token':p['token']})
 def global_state74(self,month=MONTH):return self.get('/api/budget/global?month='+month)
 def test_v74_all_frequencies_no_dates_and_no_effect_on_safe_forecast_or_ledger(self):
  joint,personal,*cards=self.banking_accounts();self.banking_apply(joint,cards)
  self.post('/api/envelopes',{'name':'Protection conservée','reserved':120,'budget':230,'frequency':'weekly','start_on':self.future73(),'rollover':True,'forecast_spend':False});before=self.get('/api/state');ledger=self.get('/api/backup/export')['tables'];expected={'weekly':99667,'biweekly':49833,'monthly':23000,'quarterly':7667,'semiannual':3833,'yearly':1917}
  for f,amount in expected.items():
   cid=self.make_category('Objectif '+f);self.global74(cid,230,frequency=f);r=next(r for r in self.global_state74()['rows'] if r['id']==cid);self.assertEqual(r['budget_cents'],amount);self.assertEqual(r['plan']['frequency'],f);self.assertNotIn('start_on',r['plan'])
  after=self.get('/api/state');self.assertEqual((before['cash_cents'],before['safe_cents'],before['reserved_cents'],before['forecast']),(after['cash_cents'],after['safe_cents'],after['reserved_cents'],after['forecast']));export=self.get('/api/backup/export')['tables']
  for table in ['accounts','envelopes','recurring','transactions','account_transfers','envelope_renewal_log','envelope_budget_overrides']:self.assertEqual(ledger[table],export[table],table)
 def test_v74_subscriptions_four_dates_one_monthly_target_and_gap(self):
  aid=self.account();cid=self.make_category('Quatre abonnements')
